        [TestMethod]
        public void Read( )
        {
            using ( var ms = new MemoryStream( data ) )
            {
                var reader = new BinaryReader( ms );

                var lcfConverter = LcfConverterFactory.GetConverter( typeof( Actor ) );
                var actor = ( Actor ) lcfConverter.Read( reader, null );

                Assert.AreEqual( instance.ID, actor.ID );
                Assert.AreEqual( instance.Name, actor.Name );
                Assert.AreEqual( instance.Title, actor.Title );
                Assert.AreEqual( instance.CharacterName, actor.CharacterName );
                Assert.AreEqual( instance.CharacterIndex, actor.CharacterIndex );
                Assert.AreEqual( instance.Transparent, actor.Transparent );
                Assert.AreEqual( instance.InitialLevel, actor.InitialLevel );
                Assert.AreEqual( instance.FinalLevel, actor.FinalLevel );
                Assert.AreEqual( instance.CriticalHit, actor.CriticalHit );
                Assert.AreEqual( instance.CriticalHitChance, actor.CriticalHitChance );
                Assert.AreEqual( instance.FaceName, actor.FaceName );
                Assert.AreEqual( instance.FaceIndex, actor.FaceIndex );
                Assert.AreEqual( instance.TwoWeapon, actor.TwoWeapon );
                Assert.AreEqual( instance.LockEquipment, actor.LockEquipment );
                Assert.AreEqual( instance.AutoBattle, actor.AutoBattle );
                Assert.AreEqual( instance.SuperGuard, actor.SuperGuard );

                CollectionAssert.AreEqual( instance.Parameters.MaxHP, actor.Parameters.MaxHP );
                CollectionAssert.AreEqual( instance.Parameters.MaxSP, actor.Parameters.MaxSP );
                CollectionAssert.AreEqual( instance.Parameters.Attack, actor.Parameters.Attack );
                CollectionAssert.AreEqual( instance.Parameters.Defense, actor.Parameters.Defense );
                CollectionAssert.AreEqual( instance.Parameters.Spirit, actor.Parameters.Spirit );
                CollectionAssert.AreEqual( instance.Parameters.Agility, actor.Parameters.Agility );

                Assert.AreEqual( instance.ExpBase, actor.ExpBase );
                Assert.AreEqual( instance.ExpInflation, actor.ExpInflation );
                Assert.AreEqual( instance.ExpCorrection, actor.ExpCorrection );

                Assert.AreEqual( instance.InitialEquipment.WeaponID, actor.InitialEquipment.WeaponID );
                Assert.AreEqual( instance.InitialEquipment.ShieldID, actor.InitialEquipment.ShieldID );
                Assert.AreEqual( instance.InitialEquipment.ArmorID, actor.InitialEquipment.ArmorID );
                Assert.AreEqual( instance.InitialEquipment.HelmetID, actor.InitialEquipment.HelmetID );
                Assert.AreEqual( instance.InitialEquipment.AccessoryID, actor.InitialEquipment.AccessoryID );

                Assert.AreEqual( instance.UnarmedAnimation, actor.UnarmedAnimation );
                Assert.AreEqual( instance.ClassID, actor.ClassID );
                Assert.AreEqual( instance.BattleX, actor.BattleX );
                Assert.AreEqual( instance.BattleY, actor.BattleY );
                Assert.AreEqual( instance.BattlerAnimation, actor.BattlerAnimation );

                CollectionAssert.AreEqual( instance.Skills, actor.Skills );
                Assert.AreEqual( instance.RenameSkill, actor.RenameSkill );
                Assert.AreEqual( instance.SkillName, actor.SkillName );

                CollectionAssert.AreEqual( instance.StateRanks, actor.StateRanks );
                CollectionAssert.AreEqual( instance.AttributeRanks, actor.AttributeRanks );
                CollectionAssert.AreEqual( instance.BattleCommands, actor.BattleCommands );
            }
        }

        [TestMethod]
        public void Write( )
        {
            using ( var ms = new MemoryStream( ) )
            {
                var writer = new BinaryWriter( ms );

                var lcfConverter = LcfConverterFactory.GetConverter( typeof( Actor ) );
                lcfConverter.Write( writer, instance, false );

                var buffer = ms.ToArray( );
                int minLength = Math.Min( buffer.Length, data.Length );
                int contextBytes = 5; // Number of bytes to show before and after the deviation

                for ( int i = 0; i < minLength; i++ )
                {
                    if ( buffer[i] != data[i] )
                    {
                        // Show surrounding bytes for context
                        int start = Math.Max( 0, i - contextBytes );
                        int end = Math.Min( minLength - 1, i + contextBytes );

                        var bufferSnippet = string.Join( " ", buffer.Skip( start ).Take( end - start + 1 ).Select( b => $"0x{b:X2}" ) );
                        var dataSnippet = string.Join( " ", data.Skip( start ).Take( end - start + 1 ).Select( b => $"0x{b:X2}" ) );

                        Assert.Fail( $"Buffers differ at index {i}. Expected: 0x{data[i]:X2}, Actual: 0x{buffer[i]:X2}\n" +
                                    $"Written:\t{bufferSnippet}\n" +
                                    $"Expected:\t{dataSnippet}" );
                    }
                }

                // If no differences found, check if one buffer is longer than the other
                if ( buffer.Length != data.Length )
                {
                    Assert.Fail( $"Buffers have different lengths. Expected: {data.Length}, Actual: {buffer.Length}" );
                }
            }
        }
